<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {useSettlementCommand} from '../settlementCommand'
import {segmentDefaultCutoff,segmentIssue,segmentState,validSegmentDetail,type SegmentDetail,type SegmentPage} from '../segmentPayroll'
import type {PayrollHomeData} from '../payrollTypes'
import {storeToday} from '../time'
import PhaseStatus from '../components/PhaseStatus.vue'
import PayBreakdownSummary from '../components/PayBreakdownSummary.vue'
import SupplementalPaymentFields from '../components/SupplementalPaymentFields.vue'
const route=useRoute(),{api,base,load,loading,failure,english,issue}=usePayrollPage(),command=useSettlementCommand(),{locked,uncertain,failure:commandFailure}=command,x=(z:string,e:string)=>english()?e:z
const directory=ref<PayrollHomeData|null>(null),company=ref(String(route.query.companyId||'')),month=ref(String(route.query.month||storeToday().slice(0,7))),page=ref<SegmentPage|null>(null),detail=ref<SegmentDetail|null>(null),creating=ref(false),editingId=ref(''),confirming=ref(false),employee=ref(String(route.query.employeeId||'')),cutoff=ref(''),working=ref(''),payable=ref(''),units=ref(false),special=ref(false),note=ref('')
const selectedEmployee=computed(()=>page.value?.employees.find(e=>e.id===employee.value)),manualUnits=computed(()=>selectedEmployee.value&&selectedEmployee.value.basis!=='hourly'&&['manual','fixed'].includes(selectedEmployee.value.generation||'manual')),own=computed(()=>!!detail.value&&directory.value?.employeeId===detail.value.employeeId)
watch([company,month],(values,before)=>{if(values[0]!==before[0])employee.value='';if(directory.value)refresh()})
const needsRecalc=computed(()=>detail.value&&(detail.value.status==='draft'||detail.value.status==='calculated'&&(detail.value.sourceChanged||!!detail.value.calculation?.issues.length)))
function refresh(){if(locked.value)return;detail.value=null;creating.value=false;confirming.value=false;page.value=null;const c=company.value,m=month.value;if(!c||!/^\d{4}-(0[1-9]|1[0-2])$/.test(m))return;void load(()=>api().get<SegmentPage>('/payroll-segments?'+new URLSearchParams({companyId:c,month:m})),v=>{if(v.companyId===c&&v.month===m){page.value=v;const id=String(route.query.segmentId||'');if(id&&v.records.some(r=>r.id===id))void open(id)}})}
function open(id:string){if(locked.value)return;creating.value=false;confirming.value=false;note.value='';void load(()=>api().get<SegmentDetail>('/payroll-segments/'+id),v=>{if(!validSegmentDetail(v,company.value,month.value,id))throw Error('Invalid settlement');detail.value=v;employee.value=v.employeeId})}
function begin(){editingId.value='';detail.value=null;confirming.value=false;creating.value=true;note.value='';units.value=false;special.value=false;working.value='';payable.value='';cutoff.value=segmentDefaultCutoff(month.value,storeToday())}
function editDraft(){const d=detail.value;if(!d||locked.value)return;editingId.value=d.id;employee.value=d.employeeId;cutoff.value=d.cutoff;working.value=d.request.workingDays||'';payable.value=d.request.payableDays||'';units.value=d.request.unitsReviewed;special.value=d.request.specialDaysReviewed;note.value=d.request.note;creating.value=true;confirming.value=false}
function refreshProjection(){const c=company.value,m=month.value;if(page.value)page.value={...page.value,formalTotals:null};void load(()=>api().get<SegmentPage>('/payroll-segments?'+new URLSearchParams({companyId:c,month:m})),v=>{if(v.companyId!==c||v.month!==m||!Array.isArray(v.records))throw Error('Invalid settlement summary');page.value=v})}
function accept(v:SegmentDetail){detail.value=v;creating.value=false;confirming.value=false;const list=page.value?.records;if(list){const index=list.findIndex(r=>r.id===v.id);if(index<0)list.push(v);else list[index]=v}if(['confirmed','published'].includes(v.status))queueMicrotask(refreshProjection)}
function save(){if(locked.value||!employee.value||!cutoff.value||!note.value.trim())return;const id=editingId.value||crypto.randomUUID(),e=employee.value;const body={expectedVersion:editingId.value?detail.value!.version:0,companyId:company.value,employeeId:e,month:month.value,cutoff:cutoff.value,workingDays:manualUnits.value?working.value||null:null,payableDays:manualUnits.value?payable.value||null:null,unitsReviewed:units.value,specialDaysReviewed:special.value,note:note.value.trim()};void command.run<SegmentDetail>('/payroll-segments/'+id,body,'put',v=>validSegmentDetail(v,body.companyId,body.month,id,e),accept)}
function action(name:string){const d=detail.value;if(!d||locked.value||!note.value.trim())return;const id=crypto.randomUUID();void command.run<SegmentDetail>('/payroll-segments/'+d.id+'/commands/'+id,{expectedVersion:d.version,action:name,note:note.value.trim()},'post',v=>validSegmentDetail(v,d.companyId,d.month,d.id,d.employeeId)&&v.version>d.version,accept)}
function payment(id:string,body:Record<string,unknown>){const d=detail.value;if(!d)return;void command.run<SegmentDetail>('/payroll-segments/'+d.id+'/payments/'+id,body,'put',v=>validSegmentDetail(v,d.companyId,d.month,d.id,d.employeeId)&&v.payments.some(p=>p.id===id),accept)}
function problem(code:string){const v=segmentIssue(code,english());return v===code?issue(code):v}
onMounted(()=>void load(()=>api().get<PayrollHomeData>('/payroll-home'),v=>{directory.value=v;const previous=company.value;company.value=company.value||v.companies[0]?.id||'';if(previous===company.value)refresh()}))
</script>
<template><section class="wf-panel segment-payroll"><header class="wf-toolbar"><h2>{{x('独立结薪','Independent payroll settlement')}}</h2><RouterLink :to="{path:base+'/payroll',query:{companyId:company,month}}">{{x('返回工资总表','Back to payroll')}}</RouterLink></header><p class="wf-hint">{{x('离职或在职员工均可分段结薪。已结期间冻结，后续只结尚未结清部分；月底统一对账，付款单独登记。','Settle a leaver or an employed person by period. Frozen ranges are excluded from later wages; reconcile the month and record payments separately.')}}</p>
<form class="wf-filters" @submit.prevent="refresh"><label>{{x('发薪公司','Paying company')}}<select v-model="company" :disabled="locked"><option v-for="c in directory?.companies||[]" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{x('工资月份','Salary month')}}<input v-model="month" type="month" :disabled="locked"></label><button :disabled="locked||loading">{{x('查询','Query')}}</button></form><PhaseStatus :failure="failure||commandFailure" :loading="loading"/><p v-if="uncertain" role="alert">{{x('结果尚未确认，保留本页，重试同一命令。','Result unconfirmed. Keep this page and retry the same command.')}} <button @click="command.replay">{{x('重试原命令','Retry exact command')}}</button></p>
<template v-if="page&&!loading"><section v-if="page.formalTotals" class="wf-section"><h3>{{x('本月已正式结算汇总','Formal settlements to date')}}</h3><p>{{page.people}} {{x('名员工','people')}} · {{page.settlementCount}} {{x('份正式结算','settlements')}} · {{x('应发','Gross')}} SGD {{page.formalTotals.gross}} · {{x('应实发','Net payable')}} SGD {{page.formalTotals.net}} · {{x('公司总成本','Company cost')}} SGD {{page.formalTotals.employerCost}}</p><p class="wf-hint">{{x('包含普通正式工资、独立结薪和正式补发；人数去重。尚未结算的后续期间不在已结金额内。','Includes formal ordinary wages, independent settlements and supplements; people are deduplicated. Unsettled later periods are excluded.')}}</p></section>
<div class="wf-toolbar"><h3>{{x('结算记录','Settlements')}}</h3><button class="primary" :disabled="locked" @click="begin">{{x('办理新的期间','Settle another period')}}</button></div><div class="segment-records"><article v-for="d in page.records" :key="d.id" class="wf-section"><strong>{{d.employeeName}}</strong><p>{{d.from}} – {{d.cutoff}} · {{segmentState(d.status,english())}}</p><p v-if="d.calculation&&!d.calculation.issues.length&&(!d.sourceChanged||['confirmed','published'].includes(d.status))">{{x('本次应实发','This settlement net')}} SGD {{d.calculation.delta.net}} · {{x('已付','Paid')}} {{d.paid}} · {{x('未付','Remaining')}} {{d.remaining}}</p><button :disabled="locked" @click="open(d.id)">{{x('查看本次结薪','View settlement')}}</button></article><p v-if="!page.records.length" class="wf-empty">{{x('尚无独立结薪记录。','No independent settlements yet.')}}</p></div>
<form v-if="creating" class="wf-section" @submit.prevent="save"><h3>{{x('1 选择员工和截止日','1 Choose employee and cutoff')}}</h3><fieldset :disabled="locked"><div class="wf-grid"><label>{{x('员工','Employee')}}<select v-model="employee" required :disabled="!!editingId"><option value="">{{x('请选择员工','Choose employee')}}</option><option v-for="e in page.employees" :key="e.id" :value="e.id">{{e.name}}</option></select></label><label>{{x('结算截至营业日期','Settle through business date')}}<input v-model="cutoff" type="date" required :readonly="!!editingId" :min="month+'-01'" :max="segmentDefaultCutoff(month,storeToday())||storeToday()"></label></div><p class="wf-hint">{{x('系统从上一正式结算次日继续，首次从本月开始；只允许已结束日期。加班保留整周上下文。','Coverage continues after the last formal cutoff, or starts this month. Dates must be completed. Overtime retains weekly context.')}}</p><div v-if="manualUnits" class="wf-grid"><label>{{x('完整月约定工作日','Full-month contractual working days')}}<input v-model="working" inputmode="decimal" required></label><label>{{x('截至本次累计应付日','Cumulative payable days through cutoff')}}<input v-model="payable" inputmode="decimal" required></label></div><label class="segment-check"><input v-model="units" type="checkbox">{{x('已核对累计单位／无打卡资料依据','Cumulative units / no-clock evidence reviewed')}}</label><label class="segment-check"><input v-model="special" type="checkbox">{{x('已复核本次特殊日期（如有）','Special days reviewed where applicable')}}</label><label>{{x('结算说明与核对依据','Settlement note and evidence')}}<textarea v-model="note" required maxlength="500" rows="2"/></label><p class="wf-hint">{{x('收入和扣款来自有效方案与已批准本月项目。非按日分摊项目可能首段全额结算，测算后请核对。','Income and deductions use effective terms and approved monthly items. Non-prorated items may be paid in full in the first segment; review the calculation.')}}</p><footer class="wf-form-actions"><button type="button" @click="creating=false">{{x('取消','Cancel')}}</button><button class="primary">{{editingId?x('保存草稿资料','Save draft inputs'):x('建立结算草稿','Create draft')}}</button></footer></fieldset></form>
<article v-if="detail" class="wf-section"><header class="wf-toolbar"><h3>{{detail.employeeName}} · {{detail.from}} – {{detail.cutoff}}</h3><span>{{segmentState(detail.status,english())}}</span></header><p v-if="detail.sourceChanged" role="alert">{{['confirmed','published'].includes(detail.status)?x('已结来源有变化；原金额保持冻结，差额请独立补发或纠错。','Settled sources changed. Frozen amounts remain; correct separately.'):x('来源已变化，须重新测算。','Sources changed. Recalculate.')}}</p><template v-if="detail.calculation"><p v-for="code in detail.calculation.notices" :key="code" class="wf-hint">{{problem(code)}}</p><p v-for="code in detail.calculation.issues" :key="code" role="alert">{{problem(code)}}</p><RouterLink v-if="detail.calculation.issues.some(c=>c.startsWith('PROFILE_')||c.startsWith('CPF_')||c.startsWith('CDAC_')||c.includes('APPROVAL')||c==='SOURCE_PENDING')" :to="{path:base+'/payroll',query:{companyId:company,month,payEmployee:detail.employeeId}}">{{x('返回总表处理该员工来源待办','Resolve this employee’s source tasks on the payroll board')}}</RouterLink><dl class="wf-details"><dt>{{x('截至本次累计应发／应实发','Cumulative gross / net through cutoff')}}</dt><dd>{{detail.calculation.targetGross??detail.calculation.cumulative.totalGross}} / {{detail.calculation.targetNet??detail.calculation.cumulative.totalNet}}</dd><dt>{{x('此前已正式结算','Previously formally settled')}}</dt><dd>{{x('应发','Gross')}} {{detail.calculation.previouslySettled.gross}} · {{x('应实发','Net')}} {{detail.calculation.previouslySettled.net}}</dd><dt>{{x('本次公司SDL增量','Company SDL liability increment')}}</dt><dd>{{detail.calculation.companySdlDelta??'—'}}</dd></dl><PayBreakdownSummary v-if="!detail.calculation.issues.length&&(!detail.sourceChanged||['confirmed','published'].includes(detail.status))" :value="detail.calculation.delta" details business-labels/><details><summary>{{x('查看累计工时与计算依据','Cumulative hours and evidence')}}</summary><p>{{detail.calculation.cumulative.lines[0]?.workSeconds||0}} {{x('秒核准工时；项目依据及版本已保留在结算快照。','approved seconds; item evidence and versions retained in settlement.')}}</p></details></template>
<label v-if="['draft','calculated','confirmed'].includes(detail.status)">{{x('本次办理说明','Action note')}}<textarea v-model="note" :disabled="locked" maxlength="500" rows="2"/></label><section v-if="confirming" class="wf-section" role="region" :aria-label="x('确认结薪范围','Confirm covered range')"><p>{{detail.employeeName}} · {{detail.from}} – {{detail.cutoff}} · SGD {{detail.calculation?.delta.net}}</p><p>{{x('确认后冻结此期间，不能再纳入普通整月确认。发布和付款仍单独办理。','Confirmation freezes this range and excludes it from ordinary full-month confirmation. Publish and pay separately.')}}</p><button :disabled="locked" @click="confirming=false">{{x('返回核对','Back to review')}}</button><button class="primary" :disabled="locked||own||!note.trim()" @click="action('confirm')">{{x('确认冻结本次结薪','Freeze this settlement')}}</button></section>
<div v-else class="wf-form-actions"><button v-if="['draft','calculated'].includes(detail.status)" :disabled="locked" @click="editDraft">{{x('修改草稿资料','Edit draft inputs')}}</button><button v-if="needsRecalc" class="primary" :disabled="locked||!note.trim()" @click="action('calculate')">{{detail.status==='draft'?x('测算本次结薪','Calculate settlement'):x('重新测算','Recalculate')}}</button><button v-else-if="detail.status==='calculated'" class="primary" :disabled="locked||own" @click="confirming=true">{{x('确认本次结薪','Confirm settlement')}}</button><button v-else-if="detail.status==='confirmed'" class="primary" :disabled="locked||own||!note.trim()" @click="action('publish')">{{x('发布本次工资单','Publish payslip')}}</button><button v-if="['draft','calculated'].includes(detail.status)" :disabled="locked||!note.trim()" @click="action('void')">{{x('作废草稿','Void draft')}}</button></div>
<RouterLink v-if="['confirmed','published'].includes(detail.status)" :to="{path:base+'/supplemental-payroll',query:{companyId:company,employeeId:detail.employeeId,originMonth:month}}">{{x('已结期间差额：独立补发／原单付款查询','Settled-range differences: supplemental wages / original payments')}}</RouterLink><p v-if="own" class="wf-hint">{{x('不能确认、发布或登记自己的工资付款。','You cannot confirm, publish or register payment for your own wages.')}}</p><p v-if="detail.status==='published'">{{x('已发布不代表银行到账。','Publication is not proof of bank receipt.')}} {{x('已付／未付','Paid / remaining')}} {{detail.paid}} / {{detail.remaining}}</p><SupplementalPaymentFields v-if="detail.status==='published'&&!own" :key="detail.id+'-'+detail.payments.length" :title="x('本次结薪付款登记／冲正','Settlement payment / reversal')" :note-max="500" :employee-id="detail.employeeId" :settlement-month="detail.month" :remaining="detail.remaining" :payments="detail.payments" :locked="locked" @save="payment"/></article></template></section></template>
<style scoped>.segment-payroll{min-width:0;overflow-wrap:anywhere}.segment-records{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.segment-check{display:flex!important;align-items:center;gap:8px}.segment-check input{width:18px!important;height:18px;min-height:0;margin:0;padding:0;flex:0 0 auto}fieldset{min-width:0}@media(max-width:600px){.segment-records{grid-template-columns:1fr}}</style>
